def join(*paths):
    """Join multiple PyFilesystem paths into a single path.

    Absolute paths in later arguments replace the path built so far.
    """
    if not paths:
        return ""

    path = paths[0]
    for part in paths[1:]:
        if part.startswith("/"):
            path = part
        else:
            path = path.rstrip("/") + "/" + part

    return path

