def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    relevant_subtable = relevant_l33t_subtable(password, _l33t_table)

    for sub in enumerate_l33t_subs(relevant_subtable):
        if not sub:
            continue

        translated_password = translate(password, sub)

        for dictionary_match_result in dictionary_match(
                translated_password, _ranked_dictionaries):

            i = dictionary_match_result['i']
            j = dictionary_match_result['j']
            original_token = password[i:j + 1]

            # Exclude single-character matches.
            if len(original_token) <= 1:
                continue

            # Ignore direct dictionary matches that did not use a substitution.
            if original_token.lower() == dictionary_match_result['matched_word']:
                continue

            # Keep only substitutions actually present in this matched token.
            used_substitutions = {
                substituted_char: original_char
                for substituted_char, original_char in sub.items()
                if substituted_char in original_token
            }

            # Ensure that the match contains at least one actual substitution.
            if not used_substitutions:
                continue

            matches.append({
                'pattern': 'dictionary',
                'i': i,
                'j': j,
                'token': original_token,
                'matched_word': dictionary_match_result['matched_word'],
                'rank': dictionary_match_result['rank'],
                'dictionary_name': (
                    dictionary_match_result['dictionary_name']
                ),
                'reversed': False,
                'l33t': True,
                'sub': used_substitutions,
            })

    return sorted(matches, key=lambda match: (match['i'], match['j']))

def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    relevant_table = relevant_l33t_subtable(password, _l33t_table)

    for sub in enumerate_l33t_subs(relevant_table):
        if not sub:
            continue

        subbed_password = translate(password, sub)

        for match in dictionary_match(
                subbed_password, _ranked_dictionaries):
            i = match['i']
            j = match['j']
            original_token = password[i:j + 1]

            # Exclude single-character tokens.
            if len(original_token) <= 1:
                continue

            # Keep only substitutions that occur within this match.
            match_sub = {
                l33t_char: letter
                for l33t_char, letter in sub.items()
                if l33t_char in original_token
            }

            # Exclude direct dictionary matches without an actual
            # substitution in the matched token.
            if not match_sub:
                continue

            match.update({
                'token': original_token,
                'matched_word': match['matched_word'],
                'i': i,
                'j': j,
                'l33t': True,
                'sub': match_sub,
                'sub_display': ', '.join(
                    f'{l33t_char} -> {letter}'
                    for l33t_char, letter in match_sub.items()
                ),
            })
            matches.append(match)

    # Sort by the matched substring's start position, then end position.
    return sorted(matches, key=lambda match: (match['i'], match['j']))
